/** The engine's modules besides its core. */
export const DESIGNELY_RUNTIME_MODULES = ["simulation"];

let runtime = null;
const warned = new Set();

/**
 * Starts a scene in `element` and returns its handle (update, pause, play, destroy), or null if it couldn't start.
 * Never throws: a page must keep working without WebGL2.
 */
export function mountDesignely(element, scene, options) {
  const { requires = [], ...rest } = options || {};
  const missing = requires.filter((name) => !DESIGNELY_RUNTIME_MODULES.includes(name) && !warned.has(name));
  if (missing.length) {
    missing.forEach((name) => warned.add(name));
    console.warn("[designely] This designely-runtime.js lacks the " + missing.join(", ") + " module" + (missing.length > 1 ? "s" : "") + " a component needs: use the newest copy from Designely Studio.");
  }
  try {
    if (!runtime) runtime = createDesignelyRuntime();
    const handle = runtime.mount(element, scene, rest);
    // Without WebGL2 the engine draws nothing (or the scene's fallback image): say so once.
    if (handle && typeof element.querySelector === "function" && !element.querySelector("canvas") && !warned.has("webgl2")) {
      warned.add("webgl2");
      console.warn("[designely] WebGL2 isn't available in this browser, so the scene isn't drawn.");
    }
    return handle;
  } catch (error) {
    console.warn("[designely] Could not start the scene.", error);
    return null;
  }
}
